"""Böcklin lowercase, letter by letter, from a few standard parts."""
from core import K, lens, loop, W, XH
X = 510
# ---- standard parts -------------------------------------------------------------------------------------
def stem(x, y0, y1, a=True, b=True):      # the waisted stem (thick, slightly pinched in the middle)
    return K((x, y0, 90, 1), (x, (y0 + y1) / 2, 90, .97), (x, y1, 90, 1), cut=(a, b))
def foot(x): return lens(x, 0)                       # baseline lens
def top(x): return lens(x, X, up=True)               # x-height lens
def flag(x, y=700): return lens(x, y, 118, 0, up=True)   # ascender top: the lens on the left only
def arch(x0, x1, y=X, w0=.5):              # n / m / h arch: thin out of the left stem, thick into the right one
    return K((x0 + 58, y - 110, 55, w0), ((x0 + x1) / 2 + 20, y - 40, 0, .7), (x1, y - 110, -85, 1), (x1, 0, -90, 1), cut=(False, True))
def dot(x, y=625): return K((x - 70, y, 0, .38), (x, y + 6, 0, .72), (x + 70, y, 0, .38))
def bowl_r(x0, xr, y0=0, y1=X, wt=.45, wb=1.05):     # b / p bowl: out of the stem at the top, round, back in at the bottom
    cy = (y0 + y1) / 2
    return K((x0 + 40, y1 - 70, 40, wt), ((x0 + xr) / 2 + 20, y1 - 30, 0, .5), (xr - 62, cy, -90, 1), ((x0 + xr) / 2 + 20, y0 + 64, 180, wb), (x0 + 40, y0 + 70, 160, .7))
def bowl_l(x1, xl, y0=0, y1=X, wt=.5, wb=1.05):      # d / q bowl
    cy = (y0 + y1) / 2
    return K((x1 - 40, y1 - 70, 140, wt), ((x1 + xl) / 2 - 10, y1 - 30, 180, .5), (xl + 60, cy, -90, 1), ((x1 + xl) / 2 - 10, y0 + 66, 0, wb), (x1 - 40, y0 + 80, 30, .6))
def hook(x, y, d=1):                       # the curled terminal (c, e, r, a, f, j...): turns down, curls back, small ball
    return [(x, y, -90 * d if d else -90, .9), (x - 35 * d, y - 60, 180 if d > 0 else 0, .75), (x - 70 * d, y - 25, 90, .7)]
